using System;using System.IO;using System.Drawing;using System.Runtime.InteropServices;using VisionDesigner;using VisionDesigner.ImageBinary;
class Probe {
 [DllImport("kernel32",CharSet=CharSet.Unicode)] static extern bool SetDllDirectory(string path);
 static int Main(string[] args){string root=args[0],output=args[1];Directory.CreateDirectory(output);SetDllDirectory(Path.Combine(root,"Runtime","x64"));try{using(var source=new Bitmap(16,16)){for(int y=0;y<16;y++)for(int x=0;x<16;x++){int n=y*16+x;source.SetPixel(x,y,Color.FromArgb(n,n,n));}source.Save(Path.Combine(output,"input.bmp"),System.Drawing.Imaging.ImageFormat.Bmp);}using(var image=new CMvdImage()){image.InitImage(Path.Combine(output,"input.bmp"),MVD_PIXEL_FORMAT.MVD_PIXEL_MONO_08);using(var tool=new CImageBinaryTool()){tool.InputImage=image;tool.SetRunParam("BinaryType","1");tool.SetRunParam("LowThreshold","100");tool.SetRunParam("HighThreshold","150");tool.Run();tool.Result.OutputImage.SaveImage(Path.Combine(output,"full.bmp"));tool.ROI=new CMvdRectangleF(8,8,8,6);tool.Run();tool.Result.OutputImage.SaveImage(Path.Combine(output,"rectangle.bmp"));tool.SetRunParam("LowThreshold","0");tool.SetRunParam("HighThreshold","255");tool.Run();tool.Result.OutputImage.SaveImage(Path.Combine(output,"rectangle-mask.bmp"));var polygon=new CMvdPolygonF();polygon.AddVertex(3,3);polygon.AddVertex(12,3);polygon.AddVertex(10,12);polygon.AddVertex(4,10);tool.ROI=polygon;tool.Run();tool.Result.OutputImage.SaveImage(Path.Combine(output,"polygon-mask.bmp"));var center=new MVD_POINT_F();center.fX=8;center.fY=8;tool.ROI=new CMvdAnnularSectorF(center,3,6,0,90);tool.Run();tool.Result.OutputImage.SaveImage(Path.Combine(output,"sector-mask.bmp"));}}File.WriteAllText(Path.Combine(output,"success.txt"),"Original SDK executed MONO8 hard-threshold and ROI fixtures.");return 0;}catch(Exception e){File.WriteAllText(Path.Combine(output,"failure.txt"),e.ToString());Console.WriteLine(e);return 1;}}
}
